import{addWebUiListener}from"chrome://resources/js/cr.js";class Log extends EventTarget{protocolEventName_="onProtocolEvent";entries=[];constructor(){super();addWebUiListener(this.protocolEventName_,(response=>{this.log_(response)}))}log_(details){const entry={submodule:"protocol",event:this.protocolEventName_,date:new Date,details:details,textDetails:""};entry.textDetails=JSON.stringify(entry.details,null,2);this.entries.push(entry);const e=new CustomEvent("append",{bubbles:false,cancelable:false,detail:entry});this.dispatchEvent(e)}}export const log=new Log;